import { exportConfig, importConfig, summarizeImport, buildConfigWithPublishedScenario, getScenarioPublishState } from '@/functions/operational-triggers/schema';
import type { OperationalTriggerConfig } from '@/types/operational-triggers';
import { SCHEMA_VERSION } from '@/types/operational-triggers';

const sampleConfig: OperationalTriggerConfig = {
    version: SCHEMA_VERSION,
    is_active: true,
    scenarios: [
        {
            id: 's1',
            name: 'Liquidação pronta',
            enabled: true,
            event: 'due.liquidacao_ready',
            logic: 'AND',
            conditions: [],
            actions: [
                {
                    id: 'a1',
                    type: 'notify_sector',
                    target: { sector_slug: 'liquidacao' },
                    title: 'Pronta',
                    message_template: '{credor}',
                },
                {
                    id: 'a2',
                    type: 'webhook',
                    url: 'https://celer.com.br/hooks/test',
                },
            ],
        },
    ],
};

describe('operational-triggers schema', () => {
    it('export/import preserva múltiplas ações por cenário', () => {
        const exported = exportConfig(sampleConfig);
        const imported = importConfig(JSON.stringify(exported));
        expect(imported.scenarios[0].actions).toHaveLength(2);
        expect(imported.scenarios[0].actions[1].type).toBe('webhook');
    });

    it('summarizeImport retorna totais corretos', () => {
        const summary = summarizeImport(sampleConfig);
        expect(summary.totalScenarios).toBe(1);
        expect(summary.enabledScenarios).toBe(1);
        expect(summary.notifyActions).toBe(1);
    });

    it('buildConfigWithPublishedScenario publica só um card sem sobrescrever outros rascunhos', () => {
        const published: OperationalTriggerConfig = {
            version: SCHEMA_VERSION,
            is_active: true,
            scenarios: [
                sampleConfig.scenarios[0],
                {
                    ...sampleConfig.scenarios[0],
                    id: 's2',
                    name: 'Outro gatilho',
                },
            ],
        };
        const draft: OperationalTriggerConfig = {
            ...published,
            scenarios: [
                { ...published.scenarios[0], name: 'Liquidação pronta (editado)' },
                published.scenarios[1],
            ],
        };

        const payload = buildConfigWithPublishedScenario(draft, published, 's1');

        expect(payload.scenarios).toHaveLength(2);
        expect(payload.scenarios[0].name).toBe('Liquidação pronta (editado)');
        expect(payload.scenarios[1].name).toBe('Outro gatilho');
        expect(getScenarioPublishState(payload.scenarios[0], payload)).toBe('synced');
        expect(getScenarioPublishState(draft.scenarios[1], payload)).toBe('synced');
    });
});

